import com.eyeauras.insight.InsightAnchorScan;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.function.LongSupplier;

/** Opt-in offline native-core checks: generated byte arrays only, no Ghidra/process/game input. */
public class TestStringAnchors {
  static final BigInteger B=new BigInteger("180000003",16);
  static int checks=0;
  static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
  static class Memory implements InsightAnchorScan.Bytes {
    byte[] data;long reads;List<InsightAnchorScan.Span> spans;
    Memory(int size){data=new byte[size];Arrays.fill(data,(byte)0x91);spans=List.of(new InsightAnchorScan.Span(B,B.add(BigInteger.valueOf(size-1))));}
    public int read(BigInteger at,byte[] out){int index=at.subtract(B).intValueExact();check(spans.stream().anyMatch(s->at.compareTo(s.start())>=0&&at.add(BigInteger.valueOf(out.length-1)).compareTo(s.end())<=0),"Read crosses clipped span");System.arraycopy(data,index,out,0,out.length);reads+=out.length;return out.length;}
    void put(int offset,byte[] value){System.arraycopy(value,0,data,offset,value.length);}
    void literal(int offset,String value,String encoding){int width=encoding.equals("ascii")?1:2;put(offset-width,new byte[width]);put(offset,InsightAnchorScan.encoded(value,encoding));put(offset+InsightAnchorScan.encoded(value,encoding).length,new byte[width]);}
  }
  static InsightAnchorScan.Config config(Memory m,String text,List<String> enc,int cap,int bytes,int candidates,int limit,BigInteger from,String form){return new InsightAnchorScan.Config(text,enc,B,B.add(BigInteger.valueOf(m.data.length-1)),from,form,cap,bytes,candidates,5,limit);}
  static Map<String,Object> run(Memory m,InsightAnchorScan.Config c)throws Exception{return new InsightAnchorScan(c,m.spans,m,System::nanoTime).run();}
  @SuppressWarnings("unchecked") static List<Map<String,Object>> rows(Map<String,Object> v){return (List<Map<String,Object>>)v.get("matches");}
  @SuppressWarnings("unchecked") static Map<String,Object> obj(Object v){return (Map<String,Object>)v;}
  static String at(int offset){return B.add(BigInteger.valueOf(offset)).toString(16);}
  static List<String> pairs(List<Map<String,Object>> rows){return rows.stream().map(x->x.get("matchAddress")+":"+x.get("encoding")).toList();}
  public static void main(String[] ignored)throws Exception{
    Memory m=new Memory(200000);m.literal(32,"Data/Balance/Widget.dat","ascii");m.literal(101,"Data/Balance/Widget.dat","utf16le");m.literal(5000,"ababa","ascii");m.literal(9000,"A","utf16le");
    var c=config(m,"Widget",List.of("ascii","utf16le"),1024,4194304,10000,100,B,"ascii");var v=run(m,c);var rs=rows(v);
    check(pairs(rs).equals(List.of(at(45)+":ascii",at(127)+":utf16le")),"Byte hits/odd UTF16 phase");
    for(var row:rs){var l=obj(row.get("literalCandidate"));check(Boolean.TRUE.equals(l.get("complete")),"Complete boundaries");check(l.get("text").equals("Data/Balance/Widget.dat"),"Full candidate");check(l.get("textFrom").equals(l.get("start")),"Full candidate preview start");}
    check(obj(v.get("scan")).get("bytesRead").equals((int)m.reads),"Every physical read metered");
    var overlap=run(m,config(m,"aba",List.of("ascii"),1024,4194304,10000,100,B,"ascii"));check(pairs(rows(overlap)).equals(List.of(at(5000)+":ascii",at(5002)+":ascii")),"Overlapping hits retained");
    var both=config(m,"A",List.of("ascii","utf16le"),1024,4194304,10000,1,B.add(BigInteger.valueOf(9000)),"ascii");var first=run(m,both);var next=obj(obj(first.get("scan")).get("next"));check(next.get("address").equals(at(9000))&&next.get("encoding").equals("utf16le"),"Frontier between encodings");
    var second=run(m,config(m,"A",List.of("ascii","utf16le"),1024,32768,10000,1,new BigInteger((String)next.get("address"),16),(String)next.get("encoding")));check(rows(second).getFirst().get("encoding").equals("utf16le"),"Minimum budget consumes resumed candidate");
    Memory longOne=new Memory(50000);longOne.literal(5000,"x".repeat(4000)+"Widget"+"y".repeat(4000),"ascii");
    var longHit=run(longOne,config(longOne,"Widget",List.of("ascii"),8192,32768,1,1,B.add(BigInteger.valueOf(9000)),"ascii"));var lc=obj(rows(longHit).getFirst().get("literalCandidate"));check(Boolean.TRUE.equals(lc.get("complete")),"Asymmetric full candidate at maximum cap progresses");check(lc.get("byteLength").equals(8006),"Full candidate total cap");
    var clipped=run(longOne,config(longOne,"Widget",List.of("ascii"),1024,32768,100,100,B,"ascii"));var partial=obj(rows(clipped).getFirst().get("literalCandidate"));check(partial.get("start")==null&&partial.get("terminatorAddress")==null,"Missing boundaries do not fabricate start/end");check(partial.get("textByteLength").equals(1024)&&partial.get("textFrom").equals(at(8491)),"Deterministic balanced preview");check(partial.get("reason").equals("string_limit"),"Context cap explicit");
    Memory invalid=new Memory(64);invalid.put(14,new byte[]{0,(byte)0xff,'W','i','d','g','e','t',0});var bad=run(invalid,config(invalid,"Widget",List.of("ascii"),1024,32768,100,100,B,"ascii"));var il=obj(rows(bad).getFirst().get("literalCandidate"));check(il.get("boundariesComplete").equals(true)&&il.get("decoding").equals("invalid")&&il.get("text")==null,"Invalid context keeps raw hit and boundary evidence");
    Memory edges=new Memory(24);edges.put(0,InsightAnchorScan.encoded("Widget","ascii"));var edge=run(edges,config(edges,"Widget",List.of("ascii"),1024,32768,100,100,B,"ascii"));check(obj(rows(edge).getFirst().get("literalCandidate")).get("leftBoundary").equals("range_edge"),"Range edge not NUL");
    Memory holes=new Memory(100);holes.spans=List.of(new InsightAnchorScan.Span(B,B.add(BigInteger.valueOf(20))),new InsightAnchorScan.Span(B.add(BigInteger.valueOf(22)),B.add(BigInteger.valueOf(99))));holes.put(19,InsightAnchorScan.encoded("Widget","ascii"));var noBridge=run(holes,config(holes,"Widget",List.of("ascii"),1024,32768,100,100,B,"ascii"));check(rows(noBridge).isEmpty(),"No match across hole; every read clipped");
    Memory sparse=new Memory(150000);sparse.literal(140000,"Widget","ascii");var initial=config(sparse,"Widget",List.of("ascii","utf16le"),8192,32768,100,100,B,"ascii");List<Map<String,Object>> pages=new ArrayList<>();int count=0;
    while(true){var page=run(sparse,initial);pages.addAll(rows(page));var scan=obj(page.get("scan"));count++;if((boolean)scan.get("complete"))break;var n=obj(scan.get("next"));check(!n.get("address").equals(initial.resume().toString(16))||!n.get("encoding").equals(initial.resumeEncoding()),"Byte-budget continuation progresses");initial=config(sparse,"Widget",List.of("ascii","utf16le"),8192,32768,100,100,new BigInteger((String)n.get("address"),16),(String)n.get("encoding"));check(count<20,"Finite pages");}
    check(count>1&&pairs(pages).equals(List.of(at(140000)+":ascii")),"Paged/unpaged raw equivalence");
    Memory atomic=new Memory(100000);atomic.literal(32760,"x".repeat(2)+"Widget"+"y".repeat(4000),"ascii");
    var stopped=run(atomic,config(atomic,"Widget",List.of("ascii"),8192,32768,100,100,B,"ascii"));var stop=obj(stopped.get("scan"));check(stop.get("reason").equals("byte_limit")&&rows(stopped).isEmpty(),"Spent scan budget stops before unfinished candidate");var frontier=obj(stop.get("next"));
    var retry=run(atomic,config(atomic,"Widget",List.of("ascii"),8192,32768,100,1,new BigInteger((String)frontier.get("address"),16),(String)frontier.get("encoding")));check(rows(retry).size()==1&&Boolean.TRUE.equals(obj(rows(retry).getFirst().get("literalCandidate")).get("complete")),"Fresh minimum-budget continuation finalizes same candidate");
    check(atomic.reads>100000||atomic.reads>(int)stop.get("bytesRead"),"Continuation rereads contribute to actual physical accounting");check((int)stop.get("bytesRead")+(int)obj(retry.get("scan")).get("bytesRead")==atomic.reads,"Page totals include physical rereads");
    Random random=new Random(7);
    for(int trial=0;trial<30;trial++){
      Memory generated=new Memory(12000);random.nextBytes(generated.data);for(int j=0;j<20;j++){int where=2+random.nextInt(11900);generated.literal(where,"aba",j%2==0?"ascii":"utf16le");}
      var actual=run(generated,config(generated,"aba",List.of("ascii","utf16le"),1024,4194304,10000,1000,B,"ascii"));List<String> expected=new ArrayList<>();
      for(int a=0;a<generated.data.length;a++)for(String e:List.of("ascii","utf16le")){byte[] needle=InsightAnchorScan.encoded("aba",e);boolean equal=a+needle.length<=generated.data.length;for(int j=0;equal&&j<needle.length;j++)equal=generated.data[a+j]==needle[j];if(equal)expected.add(at(a)+":"+e);}
      check(pairs(rows(actual)).equals(expected),"Seeded raw byte-pair oracle");check(obj(actual.get("scan")).get("bytesRead").equals((int)generated.reads),"Randomized physical-byte accounting");
    }
    Memory output=new Memory(110000);output.literal(2,"\"".repeat(8000)+"Widget","ascii");List<String> many=new ArrayList<>();for(int i=0;i<80;i++)output.literal(12000+i*1000,"Widget"+"\\".repeat(900),"ascii");
    var outputConfig=config(output,"Widget",List.of("ascii"),8192,4194304,100000,1000,B,"ascii");var one=run(output,outputConfig);check(obj(one.get("scan")).get("reason").equals("result_limit"),"Envelope reserve stops dense escaped rows");
    while(true){many.addAll(pairs(rows(one)));if(Boolean.TRUE.equals(obj(one.get("scan")).get("complete")))break;var n=obj(obj(one.get("scan")).get("next"));one=run(output,config(output,"Widget",List.of("ascii"),8192,4194304,100000,1000,new BigInteger((String)n.get("address"),16),(String)n.get("encoding")));check(many.size()<200,"Finite result-limit continuation");}
    check(many.size()==81&&new HashSet<>(many).size()==81,"Output-cap stop preserves all unreturned rows without replay");
    Memory empty=new Memory(1);empty.spans=List.of();check(obj(run(empty,config(empty,"A",List.of("ascii"),16,32768,1,1,B,"ascii")).get("scan")).get("complete").equals(true),"Empty eligible domain exhausted");
    long[] time={0};LongSupplier timeout=()->{time[0]+=1000000000L;return time[0];};var timed=new InsightAnchorScan(config(m,"zzz",List.of("ascii"),1024,32768,100,100,B,"ascii"),m.spans,m,timeout).run();check(obj(timed.get("scan")).get("reason").equals("timeout"),"Cooperative no-match timeout");
    System.out.println("Native string-anchor core PASS; assertions="+checks);
  }
}
